#ifdef EXACT_HAVE_FRAME_ATTRIBUTION
// @ref LLP 0013#mechanism-3 — the vm::Runtime pointer used by the exported
// attribution bridge, cached from HermesRuntime::getVMRuntimeUnsafe() when the
// runtime is created. THREAD-LOCAL: a vm::Runtime is single-threaded and every
// host-boundary attribution walk (currentPrincipalId/checkCapability) resolves
// the JS frame executing on the *current* thread, so this must name the runtime
// this thread created — never another thread's. It sits alongside the already
// thread-local g_active_module_id / g_native_callback_principal_id principal
// state above. A process-global here is a data race: any thread creating or
// destroying its own runtime clobbers/frees the pointer a concurrently-evaling
// thread is about to walk, faulting inside getCurrentPackageId(). Ibex's product
// path (one runtime, one thread) is unaffected; the unit-test harness and
// worklet threads create runtimes concurrently and hit the race. (ENG-23011)
thread_local void* g_vm_runtime = nullptr;
#endif

// Concrete Buffer for static HBC byte arrays (used by precompiled bootstrap)
#ifdef HAS_PRECOMPILED_BOOTSTRAP
class StaticHBCBuffer : public facebook::jsi::Buffer {
    const uint8_t* data_;
    size_t size_;
public:
    StaticHBCBuffer(const uint8_t* data, size_t size) : data_(data), size_(size) {}
    size_t size() const override { return size_; }
    const uint8_t* data() const override { return data_; }
};
#endif

// Process start time for process.uptime()
static const auto g_process_start_time = std::chrono::steady_clock::now();

bool startup_trace_enabled() {
  static int cached = -1;
  if (cached < 0) {
    const char* val = std::getenv("EX_STARTUP_TRACE");
    cached = (val && (val[0] == '1' || val[0] == 'y' || val[0] == 'Y')) ? 1 : 0;
  }
  return cached == 1;
}

bool env_flag_enabled(const char* env_name) {
  // Shared truthiness parse: a leading 1/y/Y/t/T enables (so `1`, `yes`, `true`
  // all work), everything else (0/false/no/off/empty/unset) disables. The Rust
  // `env_flag_enabled` (src/bin/ibex/main.rs) mirrors this so the bundler driver
  // and the engine never disagree about whether compartments are on. (ENG-22634)
#if defined(_WIN32)
  // @ref LLP 0003#how-hermes-is-driven — the DLL's CRT environment can be a
  // separate snapshot from Rust's process environment; query the process block
  // so pre-construction runtime configuration is shared across that boundary.
  DWORD required = GetEnvironmentVariableA(env_name, nullptr, 0);
  if (required == 0) return false;
  std::string value(required, '\0');
  DWORD copied = GetEnvironmentVariableA(env_name, value.data(), required);
  const char* val = copied > 0 && copied < required ? value.c_str() : nullptr;
#else
  const char* val = std::getenv(env_name);
#endif
  return val && (val[0] == '1' || val[0] == 'y' || val[0] == 'Y' ||
                 val[0] == 't' || val[0] == 'T');
}

