bool isAndroidStorageHostPathEnvironmentKey(const std::string& key) {
#if defined(EXACT_PLATFORM_ANDROID)
  // Android initialization seeds these keys with Context backing paths. Even
  // an env:read grant cannot turn a private native storage root into an armed
  // JavaScript projection.
  // @ref LLP 0023#6-path-bearing-observables
  return key == "HOME" || key == "TMPDIR" || key == "TEMP" || key == "TMP" ||
      key == "EXACT_ANDROID_FILES_DIR" ||
      key == "EXACT_ANDROID_CACHE_DIR" ||
      key == "EXACT_ANDROID_NO_BACKUP_FILES_DIR" ||
      key == "EXACT_ANDROID_CODE_CACHE_DIR" ||
      key == "EXACT_ANDROID_EXTERNAL_FILES_DIR";
#else
  (void)key;
  return false;
#endif
}

bool isPrivateProcessIpcEnvironmentKey(const std::string& key) {
  // These inherited values are a native construction handshake, not public
  // process environment. Unarmed compatibility runtimes otherwise expose the
  // host environment, so suppress the raw startup copies there too; an explicit
  // later JavaScript override remains ordinary process.env state in its proxy.
  // @ref LLP 0022#7-capabilities-principals-and-affordance-parity
  // @ref LLP 0025#2-startup-configuration-is-captured-before-arming
  return key == "EXACT_IPC_FD" || key == "EXACT_IPC_SERIALIZATION";
}

// Returns the value of `key`, or std::nullopt when the variable is unset (kept
// distinct from a present-but-empty value). Grows past the initial stack buffer
// so a value >= 4096 bytes (e.g. a long PATH) is read in full rather than being
// silently clipped to the buffer size (ENG-22955).
std::optional<std::string> getEnvValue(const std::string& key) {
  char buffer[4096];
  int64_t needed = ex_host_env_get(key.c_str(), buffer, sizeof(buffer));
  if (needed < 0) {
    return std::nullopt;  // unset
  }
  size_t fullLen = static_cast<size_t>(needed);
  if (fullLen < sizeof(buffer)) {
    return std::string(buffer, buffer + fullLen);
  }
  // The value did not fit the stack buffer; allocate exactly and re-query.
  std::string result(fullLen, '\0');
  int64_t written =
      ex_host_env_get(key.c_str(), result.data(), static_cast<uint32_t>(fullLen + 1));
  if (written < 0) {
    return std::nullopt;  // raced to unset between the two calls
  }
  result.resize(std::min(static_cast<size_t>(written), fullLen));
  return result;
}

std::optional<std::string> getCompiledEnvKey(size_t index) {
  char buffer[256];
  int64_t needed =
      ex_host_env_compiled_key_at(index, buffer, sizeof(buffer));
  if (needed < 0) return std::nullopt;
  size_t fullLen = static_cast<size_t>(needed);
  if (fullLen < sizeof(buffer)) {
    return std::string(buffer, buffer + fullLen);
  }
  std::string result(fullLen, '\0');
  int64_t written = ex_host_env_compiled_key_at(
      index, result.data(), static_cast<uint32_t>(fullLen + 1));
  if (written < 0) return std::nullopt;
  result.resize(std::min(static_cast<size_t>(written), fullLen));
  return result;
}

std::optional<std::string> getAmbientEnvValue(const std::string& key) {
  char buffer[4096];
  int64_t needed = ex_host_env_ambient_get(key.c_str(), buffer, sizeof(buffer));
  if (needed < 0) {
    return std::nullopt;  // unset (or projection inactive)
  }
  size_t fullLen = static_cast<size_t>(needed);
  if (fullLen < sizeof(buffer)) {
    return std::string(buffer, buffer + fullLen);
  }
  std::string result(fullLen, '\0');
  int64_t written = ex_host_env_ambient_get(
      key.c_str(), result.data(), static_cast<uint32_t>(fullLen + 1));
  if (written < 0) {
    return std::nullopt;  // raced to unset between the two calls
  }
  result.resize(std::min(static_cast<size_t>(written), fullLen));
  return result;
}

std::optional<std::string> getAmbientEnvKey(size_t index) {
  char buffer[256];
  int64_t needed = ex_host_env_ambient_key_at(index, buffer, sizeof(buffer));
  if (needed < 0) return std::nullopt;
  size_t fullLen = static_cast<size_t>(needed);
  if (fullLen < sizeof(buffer)) {
    return std::string(buffer, buffer + fullLen);
  }
  std::string result(fullLen, '\0');
  int64_t written = ex_host_env_ambient_key_at(
      index, result.data(), static_cast<uint32_t>(fullLen + 1));
  if (written < 0) return std::nullopt;
  result.resize(std::min(static_cast<size_t>(written), fullLen));
  return result;
}

void runNextTickQueue(ExactHermesRuntime* runtime);

// Native StringBuffer for O(1) amortized string append (avoids O(n^2) JS string concatenation)
class StringBufferHostObject : public facebook::jsi::HostObject {
public:
  std::string buffer;

  facebook::jsi::Value get(facebook::jsi::Runtime& rt, const facebook::jsi::PropNameID& name) override {
    auto propName = name.utf8(rt);
    if (propName == "append") {
      return facebook::jsi::Function::createFromHostFunction(rt, name, 1,
          [this](facebook::jsi::Runtime& rt, const facebook::jsi::Value&,
                 const facebook::jsi::Value* args, size_t count) -> facebook::jsi::Value {
            if (count > 0) {
              buffer += args[0].asString(rt).utf8(rt);
            }
            return facebook::jsi::Value::undefined();
          });
    }
    if (propName == "toString") {
      return facebook::jsi::Function::createFromHostFunction(rt, name, 0,
          [this](facebook::jsi::Runtime& rt, const facebook::jsi::Value&,
                 const facebook::jsi::Value*, size_t) -> facebook::jsi::Value {
            return facebook::jsi::String::createFromUtf8(rt, buffer);
          });
    }
    if (propName == "length") {
      return facebook::jsi::Value(static_cast<int>(buffer.size()));
    }
    if (propName == "clear") {
      return facebook::jsi::Function::createFromHostFunction(rt, name, 0,
          [this](facebook::jsi::Runtime&, const facebook::jsi::Value&,
                 const facebook::jsi::Value*, size_t) -> facebook::jsi::Value {
            buffer.clear();
            return facebook::jsi::Value::undefined();
          });
    }
    if (propName == "reserve") {
      return facebook::jsi::Function::createFromHostFunction(rt, name, 1,
          [this](facebook::jsi::Runtime&, const facebook::jsi::Value&,
                 const facebook::jsi::Value* args, size_t count) -> facebook::jsi::Value {
            if (count > 0) {
              buffer.reserve(static_cast<size_t>(args[0].asNumber()));
            }
            return facebook::jsi::Value::undefined();
          });
    }
    return facebook::jsi::Value::undefined();
  }

  void set(facebook::jsi::Runtime&, const facebook::jsi::PropNameID&, const facebook::jsi::Value&) override {}

  std::vector<facebook::jsi::PropNameID> getPropertyNames(facebook::jsi::Runtime& rt) override {
    std::vector<facebook::jsi::PropNameID> props;
    props.push_back(facebook::jsi::PropNameID::forAscii(rt, "append"));
    props.push_back(facebook::jsi::PropNameID::forAscii(rt, "toString"));
    props.push_back(facebook::jsi::PropNameID::forAscii(rt, "length"));
    props.push_back(facebook::jsi::PropNameID::forAscii(rt, "clear"));
    props.push_back(facebook::jsi::PropNameID::forAscii(rt, "reserve"));
    return props;
  }
};

// --- Spawn env helpers (used by __exactSpawnSync and __exactSpawn) ---

